import { defineStore } from 'pinia'
import { PERMISSION_CATALOG, type PermissionCode } from '~/utils/permissions'

export interface CatalogPermission {
  id?: string
  code: string
  name: string
  module: string
  description?: string
}

/**
 * Permissions store.
 * - userCodes: from GET /auth/me (always after login)
 * - catalog: static fallback + auto-sync from GET /api/v1/permissions when allowed
 */
export const usePermissionsStore = defineStore('permissions', {
  state: () => ({
    /** Permission codes granted to the current user */
    userCodes: [] as string[],
    isSuperAdmin: false,
    /** Full system catalog (static seed, then API overwrite) */
    catalog: PERMISSION_CATALOG.map((c) => ({
      code: c.code,
      name: c.name,
      module: c.module,
      description: c.description,
    })) as CatalogPermission[],
    catalogSynced: false,
    catalogSyncError: null as string | null,
    lastSyncedAt: null as string | null,
  }),

  getters: {
    codeSet: (s) => new Set(s.userCodes),
    hasAny: (s) => {
      return (...codes: string[]) => {
        if (s.isSuperAdmin) return true
        if (!codes.length) return true
        return codes.some((c) => s.userCodes.includes(c))
      }
    },
    hasAll: (s) => {
      return (...codes: string[]) => {
        if (s.isSuperAdmin) return true
        return codes.every((c) => s.userCodes.includes(c))
      }
    },
    modules: (s) => {
      const set = new Set(s.catalog.map((c) => c.module))
      return Array.from(set).sort()
    },
  },

  actions: {
    /** Apply user grants from /auth/me */
    setUserGrants(codes: string[], isSuperAdmin: boolean) {
      this.userCodes = [...codes]
      this.isSuperAdmin = isSuperAdmin
    },

    clearUser() {
      this.userCodes = []
      this.isSuperAdmin = false
    },

    /**
     * Fetch full permission catalog from API.
     * Requires roles.view (or super admin). Fails softly for other roles.
     */
    async syncCatalogFromApi(api: <T>(path: string, opts?: object) => Promise<T>) {
      try {
        const res = await api<{ items: CatalogPermission[] }>('/permissions')
        if (res.items?.length) {
          this.catalog = res.items.map((p) => ({
            id: p.id,
            code: p.code,
            name: p.name,
            module: p.module || 'Other',
            description: p.description || '',
          }))
          this.catalogSynced = true
          this.catalogSyncError = null
          this.lastSyncedAt = new Date().toISOString()
        }
      } catch (e: any) {
        // Keep static catalog; note error for admin UI
        this.catalogSyncError = e?.data?.error || e?.message || 'sync failed'
        this.catalogSynced = false
      }
    },
  },
})

import type { User, LoginResponse } from '~/types/api'
import { useApiBase } from '~/composables/useApiBase'

const accessToken = ref<string | null>(null)
const currentUser = ref<User | null>(null)
const authReady = ref(false)

export function useAuth() {
  const apiBase = useApiBase()

  async function login(identifier: string, password: string) {
    const res = await $fetch<LoginResponse>(`${apiBase}/auth/login`, {
      method: 'POST',
      body: { identifier, password },
      credentials: 'include',
    })
    accessToken.value = res.access_token
    // Load full profile with permissions
    await fetchMe()
    return res
  }

  async function fetchMe() {
    if (!accessToken.value) {
      currentUser.value = null
      return null
    }
    try {
      const me = await $fetch<User>(`${apiBase}/auth/me`, {
        headers: { Authorization: `Bearer ${accessToken.value}` },
        credentials: 'include',
      })
      currentUser.value = me
      try {
        const store = usePermissionsStore()
        store.setUserGrants(me.permissions || [], !!me.is_super_admin)
      } catch { /* pinia may not be ready in rare cases */ }
      return me
    } catch {
      accessToken.value = null
      currentUser.value = null
      try { usePermissionsStore().clearUser() } catch { /* ignore */ }
      return null
    }
  }

  async function logout() {
    try {
      if (accessToken.value) {
        await $fetch(`${apiBase}/auth/logout`, {
          method: 'POST',
          headers: { Authorization: `Bearer ${accessToken.value}` },
          credentials: 'include',
        })
      }
    } catch {
      // ignore
    }
    accessToken.value = null
    currentUser.value = null
    try { usePermissionsStore().clearUser() } catch { /* ignore */ }
  }

  async function tryRefresh() {
    try {
      const res = await $fetch<{ access_token: string }>(`${apiBase}/auth/refresh`, {
        method: 'POST',
        credentials: 'include',
      })
      accessToken.value = res.access_token
      await fetchMe()
      return true
    } catch {
      accessToken.value = null
      currentUser.value = null
      return false
    }
  }

  function hasPermission(...codes: string[]) {
    if (!currentUser.value) return false
    if (currentUser.value.is_super_admin) return true
    const perms = currentUser.value.permissions || []
    return codes.some((c) => perms.includes(c))
  }

  function getToken() {
    return accessToken.value
  }

  async function initAuth() {
    if (authReady.value) return
    if (!accessToken.value) {
      await tryRefresh()
    } else {
      await fetchMe()
    }
    authReady.value = true
  }

  return {
    accessToken: readonly(accessToken),
    user: readonly(currentUser),
    authReady: readonly(authReady),
    login,
    logout,
    fetchMe,
    tryRefresh,
    hasPermission,
    getToken,
    initAuth,
  }
}

import { useAuth } from '~/composables/useAuth'

export default defineNuxtRouteMiddleware(async (to) => {
  const publicPaths = ['/login', '/access-denied']
  if (publicPaths.includes(to.path)) return

  // Auth lives in the browser and its refresh token is an HttpOnly cookie.
  // Let the client restore it; an SSR fetch to the external API has no browser cookie.
  if (import.meta.server) return

  const { initAuth, user, authReady } = useAuth()
  if (!authReady.value) {
    await initAuth()
  }
  if (!user.value) {
    return navigateTo('/login')
  }
})

import { useApiBase } from '~/composables/useApiBase'

export function useApi() {
  const apiBase = useApiBase()
  const { getToken, tryRefresh, logout } = useAuth()

  async function api<T>(path: string, opts: {
    method?: string
    body?: unknown
    query?: Record<string, string | number | undefined>
  } = {}): Promise<T> {
    const headers: Record<string, string> = {}
    const token = getToken()
    if (token) headers.Authorization = `Bearer ${token}`

    const query = opts.query
      ? '?' + Object.entries(opts.query)
          .filter(([, v]) => v !== undefined && v !== '')
          .map(([k, v]) => `${encodeURIComponent(k)}=${encodeURIComponent(String(v))}`)
          .join('&')
      : ''

    try {
      return await $fetch<T>(`${apiBase}${path}${query}`, {
        method: (opts.method || 'GET') as any,
        body: opts.body as any,
        headers,
        credentials: 'include',
      })
    } catch (e: any) {
      if (e?.status === 401 || e?.statusCode === 401) {
        const ok = await tryRefresh()
        if (ok) {
          const t2 = getToken()
          if (t2) headers.Authorization = `Bearer ${t2}`
          return await $fetch<T>(`${apiBase}${path}${query}`, {
            method: (opts.method || 'GET') as any,
            body: opts.body as any,
            headers,
            credentials: 'include',
          })
        }
        await logout()
        if (import.meta.client) {
          navigateTo('/login')
        }
      }
      throw e
    }
  }

  return { api, apiBase }
}

